const EXISTING = ["Search patient","Book appointment","Print controlled-drug label","Export to fax","Monthly report"];
const DESIRED = ["Search patient","Book appointment","Online payment","Monthly report","SMS reminder"];
function gap(existing, desired, retire) {
  function k(s) { return String(s).trim().toLowerCase(); }
  function has(list, s) { return list.some(function (x) { return k(x) === k(s); }); }
  function sx(a) { return a.slice().sort(function (x, y) { return k(x) < k(y) ? -1 : k(x) > k(y) ? 1 : 0; }); }
  var keep = existing.filter(function (x) { return has(desired, x); });
  var add = desired.filter(function (x) { return !has(existing, x); });
  var missing = existing.filter(function (x) { return !has(desired, x) && !has(retire || [], x); });
  return { keep: sx(keep).map(function (s) { return String(s).trim(); }), add: sx(add).map(function (s) { return String(s).trim(); }), missing: sx(missing).map(function (s) { return String(s).trim(); }) };
}
